// from src/locales/de/blog.ts. Body + FAQs for article 'gif-vs-webp-vs-mp4-animated' (de).
// This file is the single source for this article's de body text.
import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>Drei Formate konkurrieren um animierte Bilder im Web: GIF, WebP und MP4. Sie sehen auf dem Bildschirm ähnlich aus, aber ihre Dateigrößen unterscheiden sich enorm.</p>\n<p>Ein zehnsekündiger Clip wiegt vielleicht 20 MB als GIF, 8 MB als animiertes WebP und 2 MB als MP4. Das falsche Format zu wählen, verschwendet Bandbreite und verlangsamt die Seite.</p>\n<p>Dieser Vergleich erklärt, wie jedes Format funktioniert, wo jedes gewinnt und wie man zwischen ihnen wählt.</p>\n<h2 id=\"short-answer\">Die Kurzantwort</h2>\n<p>Verwenden Sie GIF für kurze Schleifen, die überall ohne Player abspielen müssen. Verwenden Sie animiertes WebP für bessere Komprimierung bei breiter Browserunterstützung. Verwenden Sie MP4 für alles, was länger als ein paar Sekunden ist.</p>\n<p>GIF ist die universelle Wahl. WebP ist die effiziente Wahl. MP4 ist die praktische Wahl für echte Videoclips.</p>\n<p>Im Zweifel fragen Sie, wie lang die Animation ist. Unter drei Sekunden ist GIF in Ordnung. Über zehn Sekunden gewinnt MP4 mit großem Abstand.</p>\n<h2 id=\"gif-format\">GIF: Das universelle Format</h2>\n<p>GIF stammt aus dem Jahr 1987 und ist damit das älteste Format im Web. Sein Alter ist auch seine Stärke: Alles unterstützt es.</p>\n<p>Jeder Browser, jede Chat-App, jeder E-Mail-Client und jede soziale Plattform spielt GIFs automatisch ab. Kein Player, kein Plugin und kein Fallback nötig.</p>\n<p>GIF speichert bis zu 256 Farben pro Frame und verwendet Komprimierung ohne Verluste pro Frame. Das klingt gut, aber es komprimiert schlecht im Vergleich zu Video.</p>\n<p>Ein GIF läuft automatisch in Schleife und spielt ohne Ton. Dieses Verhalten passt perfekt zu Reaktionen, Stickern und kurzen Witzen.</p>\n<p>Die Schwäche ist die Größe. GIFs sind schwer, und ein langes GIF kann mehr wiegen als der Rest der Seite zusammen.</p>\n<h2 id=\"webp-format\">Animiertes WebP: Der moderne Mittelweg</h2>\n<p>Animiertes WebP ist Googles modernes Bildformat mit Animationsunterstützung. Es behält die einfache Wiedergabe von GIF bei weit besserer Komprimierung.</p>\n<p>WebP unterstützt sowohl Animation mit Verlusten als auch ohne Verluste sowie einen Alpha-Kanal für Transparenz. Es kann 24-Bit-Farbe speichern, im Gegensatz zur 256-Farben-Grenze von GIF.</p>\n<p>Die Dateigrößen liegen etwa bei der Hälfte von GIF für dieselbe Animation. Ein 20-MB-GIF wird oft zu einem 8-MB-WebP mit sichtbar besseren Farben.</p>\n<p>Die Browserunterstützung ist breit. Chrome, Firefox, Safari und Edge spielen alle animiertes WebP ab, manche Chat-Apps und ältere Systeme aber nicht.</p>\n<p>WebP ist die beste Wahl für Websites, die kleinere Animationen wollen, ohne die einfache Wiedergabe aufzugeben. Es ist das vernünftige Upgrade von GIF.</p>\n<h2 id=\"mp4-format\">MP4: Video, kein Bild</h2>\n<p>MP4 ist ein Videoformat, kein Bildformat. Es verwendet Komprimierung zwischen Frames und speichert nur die Änderungen zwischen den Frames statt jeden Frame.</p>\n<p>Diese Technik macht MP4 dramatisch kleiner. Ein Clip, der als GIF 20 MB wiegt, wiegt als MP4 vielleicht 2 MB – eine zehnfache Ersparnis.</p>\n<p>MP4 unterstützt Ton, hohe Auflösungen und flüssige Wiedergabe mit 30 oder 60 Bildern pro Sekunde. Es ist für echtes Video gebaut, nicht für Daumenkinos.</p>\n<p>Der Haken ist die Wiedergabe. MP4 braucht ein Videoplayer-Element, mit Autoplay, Stumm und Schleife, um sich wie ein GIF zu verhalten.</p>\n<p>Für Clips, die länger als ein paar Sekunden sind, ist MP4 die einzig vernünftige Wahl. Die Größenersparnis ist zu groß, um sie zu ignorieren.</p>\n<h2 id=\"file-size-compared\">Dateigröße im direkten Vergleich</h2>\n<p>Nehmen Sie eine zehnsekündige Bildschirmaufnahme. Als GIF wiegt sie vielleicht 15 MB, als animiertes WebP etwa 6 MB und als MP4 etwa 1,5 MB.</p>\n<p>Die Verhältnisse gelten für alle Inhalte. MP4 ist etwa zehnmal kleiner als GIF, und WebP liegt dazwischen bei etwa der Hälfte von GIF.</p>\n<p>Kurze Animationen verkleinern die Lücke. Eine zweisekündige Reaktion von 1 MB wird zu einem 500-KB-WebP und einem 200-KB-MP4, wo die absolute Ersparnis klein ist.</p>\n<p>Lange Animationen vergrößern sie. Ein dreißigsekündiger Clip ist als GIF unbrauchbar, als MP4 aber völlig in Ordnung.</p>\n<p>Wenn die Dateigröße entscheidet, gewinnt MP4 jedes Mal. Wenn universelle Wiedergabe entscheidet, gewinnt GIF. WebP gleicht beides aus.</p>\n<h2 id=\"quality-compared\">Qualität im direkten Vergleich</h2>\n<p>Die GIF-Qualität ist durch seine 256-Farben-Palette begrenzt. Fotos bändern und posterisieren, während flache Grafiken sauber bleiben.</p>\n<p>Die WebP-Qualität ist weit besser. Mit 24-Bit-Farbe und Komprimierung mit Verlusten behalten Fotos ihre glatten Verläufe und natürlichen Töne.</p>\n<p>Die MP4-Qualität ist die beste der drei. Moderne Videocodecs bewahren Details und Farben bei winzigen Dateigrößen, und 30 Bilder pro Sekunde sehen flüssig aus.</p>\n<p>Für fotografische Inhalte ist die Rangfolge klar: MP4 zuerst, WebP zweitens, GIF mit großem Abstand zuletzt.</p>\n<p>Für flache Grafiken und Cartoons verkleinert sich die Lücke. Eine einfache Animation sieht in allen drei Formaten gut aus, und die Grenzen von GIF zeigen sich kaum.</p>\n<h2 id=\"compatibility-compared\">Kompatibilität im direkten Vergleich</h2>\n<p>GIF funktioniert überall. Jede Plattform, jeder Browser und jede Chat-App seit den 1990ern spielt GIFs ohne Nachdenken ab.</p>\n<p>WebP funktioniert in allen modernen Browsern. Die Lücke liegt bei Chat-Apps, E-Mail-Clients und älteren Systemen, wo die Unterstützung lückenhaft ist.</p>\n<p>MP4 funktioniert in Browsern über das Videoelement, aber nicht als Bild. E-Mail-Clients und manche Chat-Apps spielen es nicht wie ein GIF automatisch ab.</p>\n<p>Wenn das Ziel unbekannt ist, ist GIF die sichere Wahl. Ein GIF, das abspielt, ist besser als ein WebP, das es nicht tut.</p>\n<p>Wenn das Ziel Ihre eigene Website ist, ist MP4 oder WebP die bessere Wahl. Sie kontrollieren den Player, Kompatibilität ist also kein Risiko.</p>\n<h2 id=\"when-to-use-each\">Wann man welches Format verwendet</h2>\n<p>Verwenden Sie GIF für Reaktionen, Sticker und kurze Schleifen, die im Chat geteilt werden. Seine universelle Wiedergabe zählt mehr als seine Größe für einen zweisekündigen Witz.</p>\n<p>Verwenden Sie animiertes WebP für Website-Animationen, die bessere Qualität als GIF brauchen. Es halbiert die Dateigröße und behält die einfache Wiedergabe.</p>\n<p>Verwenden Sie MP4 für Demonstrationen, Tutorials und jeden Clip, der länger als ein paar Sekunden ist. Die Größenersparnis ist enorm und die Qualität besser.</p>\n<p>Verwenden Sie MP4 mit Autoplay, stumm und Schleife, um das GIF-Verhalten auf einer Website nachzuahmen. Besucher bemerken keinen Unterschied, außer bei der Ladegeschwindigkeit.</p>\n<p>Behalten Sie das Original-GIF, wenn Sie umwandeln. Eine Umwandlung lässt sich nicht rückgängig machen, und das GIF bleibt der universelle Fallback.</p>\n<h2 id=\"converting-between\">Zwischen den Formaten umwandeln</h2>\n<p>GIF in WebP umzuwandeln, ist einfach und halbiert meist die Dateigröße. Online-Konverter und der <a href=\"/de/gif-komprimieren/\">GIF-Kompressor</a>-Arbeitsablauf bewältigen den ersten Schritt.</p>\n<p>GIF in MP4 umzuwandeln, braucht ein Videotool. Das Ergebnis ist weit kleiner, aber die Datei ist kein Bild mehr und braucht einen Videoplayer.</p>\n<p>MP4 in GIF umzuwandeln, ist möglich, aber verschwenderisch. Das GIF wird weit größer und von niedrigerer Qualität als das Video, aus dem es stammt.</p>\n<p>Wandeln Sie nur um, wenn das Ziel es verlangt. Ein GIF, das im Chat abspielen muss, sollte ein GIF bleiben, egal wie groß.</p>\n<p>Für die besten Ergebnisse beginnen Sie mit der Quelle höchster Qualität. Eine Umwandlung aus einem komprimierten GIF erbt alle Schäden des GIFs.</p>\n<h2 id=\"web-performance\">Webleistung und animierte Bilder</h2>\n<p>Animierte Bilder schaden der Seitengeschwindigkeit mehr als jeder andere Inhalt. Ein einziges schweres GIF kann die ganze Seite verzögern.</p>\n<p>Laden Sie Animationen unter dem Falz per Lazy Loading. Sie sind beim Öffnen der Seite nicht sichtbar, sie früh herunterzuladen, verschwendet also Bandbreite.</p>\n<p>Ersetzen Sie schwere GIFs durch MP4, wo möglich. Ein Videoelement mit Autoplay und Stumm verhält sich wie ein GIF bei einem Zehntel des Gewichts.</p>\n<p>Begrenzen Sie die Anzahl der Animationen pro Seite. Fünf Schleifen-GIFs konkurrieren um Aufmerksamkeit und Bandbreite, während eine fokussierte Animation besser funktioniert.</p>\n<p>Messen Sie die Seite nach dem Ersetzen von GIFs. Die Ladeverbesserung ist oft der größte einzelne Gewinn, der auf der Seite möglich ist.</p>\n<h2 id=\"accessibility-animated\">Barrierefreiheit animierter Bilder</h2>\n<p>Schleifenanimationen können manche Besucher belasten. Menschen mit Gleichgewichtsstörungen oder Epilepsie können durch blinkende oder sich drehende Inhalte geschädigt werden.</p>\n<p>Respektieren Sie die Einstellung prefers-reduced-motion. Browser können der Seite sagen, wenn ein Besucher weniger Bewegung will, und die Seite sollte Animationen daraufhin pausieren.</p>\n<p>Halten Sie Animationen kurz und sanft. Eine langsame Überblendung ist sicherer als ein schneller Blitz, und eine zweisekündige Schleife ist sicherer als eine zehnsekündige.</p>\n<p>Geben Sie animierten Bildern im Web immer Alt-Text. Screenreader brauchen eine Beschreibung dessen, was die Animation zeigt.</p>\n<p>Animation ist eine Designentscheidung mit echten Folgen. Verwenden Sie sie bedacht und bevorzugen Sie Standbilder, wenn Bewegung nichts hinzufügt.</p>\n<h2 id=\"choosing-summary\">Eine schnelle Entscheidungstabelle</h2>\n<p>Kurze Schleife im Chat: GIF. Es spielt überall ab, und die Datei ist klein genug, dass seine Ineffizienz nicht zählt.</p>\n<p>Animation auf einer Website: animiertes WebP. Es halbiert die GIF-Größe und behält die einfache Wiedergabe in modernen Browsern.</p>\n<p>Clip länger als zehn Sekunden: MP4. Die Größenersparnis ist enorm, und die Qualität ist sichtbar besser.</p>\n<p>Animation in E-Mail: GIF. E-Mail-Clients handhaben GIFs zuverlässig, während die Videounterstützung in E-Mails schlecht ist.</p>\n<p>Sticker mit Transparenz: WebP oder GIF. WebP handhabt weiche transparente Kanten besser, während GIF in mehr Chat-Apps funktioniert.</p>\n<h2 id=\"bandwidth-costs\">Bandbreitenkosten animierter Bilder</h2>\n<p>Jeder Besucher lädt jede Animation herunter, die er ansieht. Eine Seite mit drei 10-MB-GIFs kostet 30 MB pro Besucher, was sich schnell summiert.</p>\n<p>Für eine beliebte Seite ist die Bandbreitenrechnung real. GIFs durch MP4 zu ersetzen, kann die Bandbreitenkosten um neunzig Prozent senken.</p>\n<p>Mobile Besucher zahlen am meisten. Ein schweres GIF in einer gemessenen Verbindung kostet den Besucher Geld wie auch Zeit.</p>\n<p>Kleinere Animationen bedeuten auch schnellere Seiten. Eine Seite, die schnell lädt, hält Leser, während eine langsame Seite sie verliert.</p>\n<p>Die Formatwahl ist eine Kostenentscheidung ebenso wie eine Qualitätsentscheidung. Die billigste Animation ist die, die nie in voller Größe heruntergeladen werden muss.</p>\n<h2 id=\"loop-seams\">Schleifennähte und flüssige Wiedergabe</h2>\n<p>Eine gute Schleife hat keine sichtbare Naht. Der letzte Frame fließt in den ersten, und der Betrachter kann nicht sagen, wo die Animation neu startet.</p>\n<p>GIFs laufen nahtlos in Schleife, wenn der erste und der letzte Frame übereinstimmen. Ein Sprung zwischen ihnen bricht die Illusion und wirkt amateurhaft.</p>\n<p>MP4-Schleifen können stottern, wenn der Encoder Auffüllframes hinzufügt. Die meisten Player handhaben es, aber ein sichtbarer Ruck kann am Schleifenpunkt auftreten.</p>\n<p>WebP läuft wie GIF in Schleife. Das Format wurde für dieselben Anwendungsfälle entwickelt, und sein Schleifenverhalten stimmt überein.</p>\n<p>Testen Sie die Schleife, indem Sie drei volle Zyklen ansehen. Eine Naht, die einmal unsichtbar ist, wird bei der dritten Wiederholung offensichtlich.</p>\n<h2 id=\"sound-animations\">Ton und animierte Bilder</h2>\n<p>GIFs haben keinen Ton. Diese Stille ist Teil ihres Charmes im Chat, wo ein unerwartetes Geräusch unerwünscht wäre.</p>\n<p>WebP-Animationen haben auch keinen Ton. Sie verhalten sich wie GIFs und spielen überall stumm ab.</p>\n<p>MP4 unterstützt Ton, was sowohl ein Vorteil als auch ein Risiko ist. Ein Clip mit Audio braucht Stummsteuerung, und Autoplay mit Ton wird von den meisten Browsern blockiert.</p>\n<p>Für stumme Schleifen sind GIF und WebP einfacher. Für Inhalte, die Audio brauchen, ist MP4 die einzige Wahl der drei.</p>\n<p>Halten Sie Animationen auf Websites standardmäßig stumm. Besucher sollten Ton selbst wählen, er sollte ihnen nie aufgezwungen werden.</p>\n<h2 id=\"testing-formats\">Formate nebeneinander testen</h2>\n<p>Wählen Sie eine repräsentative Animation, nicht Ihre einfachste. Ein detaillierter Clip zeigt Formatunterschiede, die ein einfaches Logo verbirgt.</p>\n<p>Exportieren Sie sie als GIF, animiertes WebP und MP4. Notieren Sie die Dateigröße jeder Version und die sichtbare Qualität in voller Größe.</p>\n<p>Spielen Sie alle drei in dem Browser ab, in dem sie erscheinen werden. Prüfen Sie Flüssigkeit, Farbe und Schärfe in jeder Version.</p>\n<p>Prüfen Sie auch die Kompatibilität. Öffnen Sie jede Datei in der Chat-App oder dem E-Mail-Client, in dem sie verwendet wird, und vergewissern Sie sich, dass sie abspielt.</p>\n<p>Der Test dauert zehn Minuten und klärt die Formatfrage für Ihren Inhalt. Ihre eigenen Augen schlagen jeden allgemeinen Ratschlag.</p>\n<h2 id=\"final-verdict-formats\">Das endgültige Urteil</h2>\n<p>GIF gewinnt bei Universalität. Nichts anderes spielt an so vielen Orten mit so wenig Aufwand, und für kurze Schleifen reicht das.</p>\n<p>WebP gewinnt bei Effizienz für das Web. Es halbiert die GIF-Größe mit besseren Farben, und moderne Browser unterstützen es alle.</p>\n<p>MP4 gewinnt bei Größe und Qualität für alles, was länger als ein paar Sekunden ist. Die zehnfache Ersparnis ist zu groß, um sie zu ignorieren.</p>\n<p>Verwenden Sie alle drei. Jedes Format hat eine Aufgabe, und das Können ist, das Format an die Aufgabe anzupassen, statt ein Format überall zu erzwingen.</p>\n<p>Beginnen Sie mit der Animationslänge. Unter drei Sekunden ist GIF in Ordnung. Über zehn Sekunden verwenden Sie MP4. Dazwischen ist WebP meist die beste Antwort.</p>\n<h2 id=\"keep-testing-formats\">Formate selbst weiter testen</h2>\n<p>Jede Animation, die Sie erstellen, ist eine Gelegenheit zum Testen. Exportieren Sie sie in zwei Formaten, vergleichen Sie die Größen und schauen Sie sich beide an – praktisches Vergleichen schult Ihr Urteil besser als jede Anleitung.</p>\n<p>Mit solchen Vergleichen entwickeln Sie schnell ein Gefühl für das richtige Format, noch bevor Sie den Konverter öffnen.</p>\n<p>Die vollständige GIF-Anleitung finden Sie unter <a href=\"/de/blog/gif-komprimieren-anleitung/\">GIF-Kompressor: Die komplette Anleitung</a>. Die praktischen Schritte finden Sie unter <a href=\"/de/blog/gif-komprimieren-so-geht-es/\">GIF komprimieren: So geht es</a>. Um ein GIF zu schrumpfen, das ein GIF bleiben muss, öffnen Sie den <a href=\"/de/gif-komprimieren/\">GIF-Kompressor</a> und wählen Sie die Voreinstellung Ausgewogen.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"Ist WebP besser als GIF für Animationen?","answer":"Für Qualität und Dateigröße ja. Animiertes WebP ist etwa halb so groß wie dasselbe GIF mit besseren Farben, da es 24-Bit-Farbe unterstützt statt der 256-Farben-Palette von GIF. Bei Kompatibilität gewinnt GIF immer noch, da jede Chat-App und jeder E-Mail-Client GIFs abspielt."},{"question":"Kann ich MP4 statt GIF auf meiner Website verwenden?","answer":"Ja, und es ist meist weit besser. Verwenden Sie ein Videoelement mit Autoplay, stumm, Schleife und playsinline, damit sich das MP4 wie ein GIF verhält. Die Datei wird etwa zehnmal kleiner, und Besucher bemerken keinen Unterschied außer bei der Ladegeschwindigkeit."},{"question":"Warum verwenden Menschen immer noch GIFs, wenn MP4 so viel kleiner ist?","answer":"Weil GIFs überall ohne Player abspielen. Chat-Apps, E-Mail-Clients und soziale Plattformen handhaben GIFs automatisch, während MP4 ein Videoelement und bestimmte Attribute braucht. Für kurze Reaktionen, die im Chat geteilt werden, zählt diese Universalität mehr als die Dateigröße."},{"question":"Unterstützt animiertes WebP Transparenz?","answer":"Ja, WebP unterstützt einen Alpha-Kanal für Transparenz und handhabt weiche Kanten besser als GIF. Ein Sticker mit weichem Schatten sieht in WebP sauberer aus als in GIF, wo Transparenz auf eine vollständig transparente Farbe pro Frame begrenzt ist."},{"question":"Wie lang sollte eine Animation als GIF sein?","answer":"Halten Sie GIFs unter ein paar Sekunden. Eine zweisekündige Reaktion ist ideal, und ein zehnsekündiger Clip strapaziert das Format bereits. Längere Animationen gehören in MP4, das sie weit effizienter komprimiert und flüssiger abspielt."},{"question":"Kann ich ein GIF in MP4 umwandeln, ohne die Schleife zu verlieren?","answer":"Ja. Wandeln Sie das GIF in MP4 um und spielen Sie es dann mit aktivierter Schleife in einem Videoelement ab. Die Animation wiederholt sich nahtlos wie das Original-GIF. Behalten Sie das Original-GIF als Fallback für Plattformen, die kein Video abspielen können."}];
